//! Process-level helpers shared by the ControlHub binaries.

use std::path::Path;
use std::sync::Arc;
use std::time::Duration;

use rskafka::client::{Client, ClientBuilder};
use tracing_subscriber::EnvFilter;

/// Load `.controlhub/settings.env` (the developer's own settings, e.g. retention) and
/// `.controlhub/services.env` (generated by `just bootstrap`) if present. Real environment
/// variables win over both, settings over generated values.
pub fn load_local_env() {
    for dir in [".controlhub", "../.controlhub", "../../.controlhub"] {
        let dir = Path::new(dir);
        if dir.join("services.env").exists() || dir.join("settings.env").exists() {
            for file in local_env_files(dir) {
                let _ = dotenvy::from_path(file);
            }
            break;
        }
    }
}

/// Existing local env files in load order; earlier files win because loading never overwrites.
fn local_env_files(dir: &Path) -> Vec<std::path::PathBuf> {
    ["settings.env", "services.env"].iter().map(|f| dir.join(f)).filter(|p| p.exists()).collect()
}

/// Structured logging for ControlHub's *own* observability. JSON when
/// `CONTROLHUB_LOG_FORMAT=json`.
pub fn init_tracing(service: &str) {
    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new(format!("info,rskafka=warn,{}=info", service.replace('-', "_"))));
    let json = std::env::var("CONTROLHUB_LOG_FORMAT").is_ok_and(|v| v == "json");
    let builder = tracing_subscriber::fmt().with_env_filter(filter).with_target(false);
    if json {
        builder.json().init();
    } else {
        builder.init();
    }
}

/// Resolves when SIGINT/SIGTERM (or Ctrl+C on Windows) is received.
pub async fn shutdown_signal() {
    let ctrl_c = async {
        let _ = tokio::signal::ctrl_c().await;
    };
    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut s) => {
                s.recv().await;
            }
            Err(_) => std::future::pending::<()>().await,
        }
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
    tracing::info!("shutdown signal received");
}

pub fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_owned())
}

pub fn env_required(key: &str) -> anyhow::Result<String> {
    std::env::var(key)
        .map_err(|_| anyhow::anyhow!("missing required environment variable {key} (run `just bootstrap`)"))
}

/// Exponential backoff with full jitter.
pub fn backoff(attempt: u32, base: Duration, max: Duration) -> Duration {
    let exp = base.saturating_mul(1u32 << attempt.min(16));
    let cap = exp.min(max);
    let jitter = rand::random::<f64>();
    cap.mul_f64(jitter.max(0.1))
}

/// Connect to the broker, retrying until `deadline`.
pub async fn connect_broker(brokers: &str, deadline: Duration) -> anyhow::Result<Arc<Client>> {
    let start = std::time::Instant::now();
    let mut attempt = 0;
    loop {
        let list: Vec<String> = brokers.split(',').map(|s| s.trim().to_owned()).collect();
        // rskafka retries the bootstrap connection internally without a deadline.
        let budget = deadline.saturating_sub(start.elapsed()).max(Duration::from_secs(1));
        let built = match tokio::time::timeout(budget, ClientBuilder::new(list).build()).await {
            Ok(r) => r.map_err(|e| e.to_string()),
            Err(_) => Err("connection attempt timed out".to_owned()),
        };
        match built {
            Ok(c) => return Ok(Arc::new(c)),
            Err(e) if start.elapsed() < deadline => {
                tracing::warn!(error = %e, attempt, "broker not reachable yet, retrying");
                tokio::time::sleep(backoff(attempt, Duration::from_millis(200), Duration::from_secs(3))).await;
                attempt += 1;
            }
            Err(e) => return Err(anyhow::anyhow!("broker unreachable at {brokers}: {e}")),
        }
    }
}

/// Create the topic if it does not exist yet. Returns the partition count to use.
pub async fn ensure_topic(client: &Client, topic: &str, partitions: i32) -> anyhow::Result<i32> {
    let existing = client.list_topics().await?;
    if let Some(t) = existing.iter().find(|t| t.name == topic) {
        return Ok(t.partitions.len() as i32);
    }
    let controller = client.controller_client()?;
    match controller.create_topic(topic, partitions, 1, 10_000).await {
        Ok(()) => Ok(partitions),
        Err(e) => {
            // Another process may have created it concurrently.
            let existing = client.list_topics().await?;
            existing
                .iter()
                .find(|t| t.name == topic)
                .map(|t| t.partitions.len() as i32)
                .ok_or_else(|| anyhow::anyhow!("failed to create topic {topic}: {e}"))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const UNSET: &str = "CONTROLHUB_RUNTIME_TEST_SURELY_UNSET_7f3a";

    #[test]
    fn env_or_falls_back_to_default() {
        assert_eq!(env_or(UNSET, "fallback"), "fallback");
        assert_eq!(env_or(UNSET, ""), "");
    }

    #[test]
    fn env_or_prefers_the_real_environment() {
        let (key, value) = std::env::vars().next().expect("test process has at least one env var");
        assert_eq!(env_or(&key, "fallback"), value);
        assert_eq!(env_required(&key).unwrap(), value);
    }

    #[test]
    fn developer_settings_load_before_generated_services_env() {
        let dir = std::env::temp_dir().join(format!("controlhub-runtime-env-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let _ = std::fs::remove_file(dir.join("settings.env"));
        std::fs::write(dir.join("services.env"), "A=1\n").unwrap();
        assert_eq!(local_env_files(&dir), [dir.join("services.env")], "settings.env is optional");
        std::fs::write(dir.join("settings.env"), "A=2\n").unwrap();
        assert_eq!(local_env_files(&dir), [dir.join("settings.env"), dir.join("services.env")]);
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn env_required_names_the_missing_variable() {
        let err = env_required(UNSET).unwrap_err().to_string();
        assert!(err.contains(UNSET), "{err}");
        assert!(err.contains("just bootstrap"), "{err}");
    }

    #[test]
    fn backoff_stays_within_jittered_cap() {
        let base = Duration::from_millis(100);
        let max = Duration::from_secs(2);
        for attempt in 0..40 {
            let cap = base.saturating_mul(1u32 << attempt.min(16)).min(max);
            for _ in 0..50 {
                let d = backoff(attempt, base, max);
                assert!(d <= cap, "attempt {attempt}: {d:?} > {cap:?}");
                assert!(d >= cap.mul_f64(0.1), "attempt {attempt}: {d:?} below the 10% floor");
            }
        }
    }

    #[test]
    fn backoff_never_overflows() {
        for attempt in [16, 17, 31, 32, 1_000, u32::MAX] {
            let day = Duration::from_secs(86_400);
            assert!(backoff(attempt, Duration::from_secs(3_600), day) <= day);
            assert!(backoff(attempt, Duration::from_millis(1), Duration::from_secs(1)) <= Duration::from_secs(1));
        }
        assert_eq!(backoff(3, Duration::ZERO, Duration::from_secs(1)), Duration::ZERO);
        assert_eq!(backoff(3, Duration::from_secs(1), Duration::ZERO), Duration::ZERO);
    }

    #[tokio::test]
    async fn connect_broker_gives_up_after_deadline_with_context() {
        // Port 1 on loopback refuses connections; a zero deadline means no retries.
        let res = tokio::time::timeout(Duration::from_secs(30), connect_broker("127.0.0.1:1", Duration::ZERO)).await;
        let err = match res {
            Ok(Err(e)) => e.to_string(),
            Ok(Ok(_)) => panic!("connected to a closed port"),
            Err(_) => panic!("connect_broker did not respect its deadline"),
        };
        assert!(err.contains("127.0.0.1:1"), "{err}");
    }
}
